-- Website tours (the Tours list, home "Most Popular Tours" and each tour page) managed from the
-- admin portal, with visitor reviews that only appear after an admin approves them.
-- Seeds the 7 tours and their reviews exactly as the website showed them before (generated from the
-- website's tour data files), so the site looks the same after the switch to the API.
-- Idempotent: tables are created once and seed rows are only added (ON CONFLICT DO NOTHING keeps
-- later edits, and reviews are added only for tours that have none yet). Nothing is updated or deleted.

CREATE TABLE IF NOT EXISTS tours (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    slug VARCHAR(160) NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),  -- page link /tour/<slug>/
    title VARCHAR(200) NOT NULL CHECK (length(trim(title)) > 0),     -- card title
    headline VARCHAR(300) NOT NULL DEFAULT '',                       -- big title on the tour page
    card_image TEXT NOT NULL,                                        -- image URLs throughout
    location VARCHAR(120) NOT NULL DEFAULT '',
    duration VARCHAR(120) NOT NULL DEFAULT '',                       -- e.g. "2 Days, 1 Night"
    activity_type VARCHAR(120) NOT NULL DEFAULT '',
    active_days VARCHAR(120) NOT NULL DEFAULT '',
    travelers INT NOT NULL DEFAULT 1 CHECK (travelers > 0),
    price VARCHAR(60) NOT NULL DEFAULT 'Contact Us',                 -- shown as written
    discount INT CHECK (discount BETWEEN 1 AND 99),                  -- percent off badge
    rating SMALLINT NOT NULL DEFAULT 5 CHECK (rating BETWEEN 1 AND 5),
    video_id VARCHAR(40) NOT NULL DEFAULT '',                        -- YouTube video id
    overview TEXT NOT NULL DEFAULT '',
    slider_images TEXT[] NOT NULL DEFAULT '{}',
    thumb_images TEXT[] NOT NULL DEFAULT '{}',                     -- 2 photos under the amenities
    highlights TEXT[] NOT NULL DEFAULT '{}',
    included TEXT[] NOT NULL DEFAULT '{}',                         -- amenities with a tick
    excluded TEXT[] NOT NULL DEFAULT '{}',                         -- amenities with a cross
    faqs JSONB NOT NULL DEFAULT '[]',                                -- Tour Plan: [{question, answer}]
    map_embed_url TEXT NOT NULL DEFAULT '',
    related_slugs TEXT[] NOT NULL DEFAULT '{}',
    is_featured BOOLEAN NOT NULL DEFAULT FALSE,                      -- shown on the home page
    is_published BOOLEAN NOT NULL DEFAULT TRUE,
    sort_order INT NOT NULL DEFAULT 0,                               -- lower first
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_tours_listing ON tours (sort_order, created_at) WHERE is_published;

CREATE TABLE IF NOT EXISTS tour_reviews (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tour_id UUID NOT NULL REFERENCES tours(id),
    name VARCHAR(100) NOT NULL,
    email VARCHAR(200),                       -- NULL for the seeded reviews
    rating SMALLINT NOT NULL CHECK (rating BETWEEN 1 AND 5),
    message TEXT NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected')),
    ip_address VARCHAR(64),
    reviewed_by UUID REFERENCES users(id),
    reviewed_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_tour_reviews_tour ON tour_reviews (tour_id, status, created_at);
CREATE INDEX IF NOT EXISTS idx_tour_reviews_status ON tour_reviews (status, created_at);

INSERT INTO tours (slug, title, headline, card_image, location, duration, activity_type, active_days, travelers, price,
    discount, rating, video_id, overview, slider_images, thumb_images, highlights, included, excluded, faqs,
    map_embed_url, related_slugs, is_featured, sort_order)
VALUES
    ('burj-khalifa', 'The Burj Khalifa', 'The tallest building in the world with breathtaking observation decks.', 'https://brightwingstravel.in/images/tourImages/burj-khalifa.jpeg', 'Dubai', '6 Days, 3 Night', 'Adventure', 'Feb 5 - 5', 1, 'Contact Us', NULL, 5, '0MuL8fd3pb8', 'The world’s tallest building,offers breathtaking panoramic views from its observation decks. A symbol of Dubai’s modern skyline, it’s a must-visit for anyone wanting a glimpse of the city from above.', ARRAY['https://brightwingstravel.in/images/sliderImage/burj-khalifa-slide-1.jpeg', 'https://brightwingstravel.in/images/sliderImage/burj-khalifa-slide-2.png', 'https://brightwingstravel.in/images/sliderImage/burj-khalifa-slide-3.png', 'https://brightwingstravel.in/images/sliderImage/burj-khalifa-slide-4.png']::text[], ARRAY['https://brightwingstravel.in/images/resources/burj-khalifa-suggestion1.jpeg', 'https://brightwingstravel.in/images/resources/burj-khalifa-suggestion2.png']::text[], ARRAY['Atmosphere Restaurant', 'The Burj Khalifa Fountains', 'Observation Decks', 'The Lounge', 'Special Events & Tours', 'Interactive Experiences']::text[], ARRAY['Cruise Dinner & Music Event', 'Pick and Drop Services', 'Additional Services', 'Specialized bilingual guide', 'Food and Drinks']::text[], ARRAY['Cruise Dinner & Music Event', 'Pick and Drop Services', 'Additional Services', 'Specialized bilingual guide', 'Food and Drinks']::text[], '[{"question":"How long should a business plan be?","answer":"Nulla facilisi. Vestibulum tristique sem in eros eleifend imperdiet. Donec quis convallis neque. In id lacus pulvinar lacus, eget vulputate lectus. Ut viverra bibendum lorem, at tempus nibh mattis in. Sed a massa eget lacus consequat auctor."},{"question":"What is included in your services?","answer":"Nulla facilisi. Vestibulum tristique sem in eros eleifend imperdiet. Donec quis convallis neque. In id lacus pulvinar lacus, eget vulputate lectus. Ut viverra bibendum lorem, at tempus nibh mattis in. Sed a massa eget lacus consequat auctor."},{"question":"What type of company is measured?","answer":"Nulla facilisi. Vestibulum tristique sem in eros eleifend imperdiet. Donec quis convallis neque. In id lacus pulvinar lacus, eget vulputate lectus. Ut viverra bibendum lorem, at tempus nibh mattis in. Sed a massa eget lacus consequat auctor."}]'::jsonb, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3610.1786541102892!2d55.27180147597446!3d25.19719697771102!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3e5f43348a67e24b%3A0xff45e502e1ceb7e2!2sBurj%20Khalifa!5e0!3m2!1sen!2sin!4v1760871030062!5m2!1sen!2sin', ARRAY['desert-safari-dubai', 'modern-dubai-frame']::text[], true, 1),
    ('dubai-mall', 'The Dubai Mall', 'The Dubai Mall - One of the largest malls in the world with shops, an aquarium, and an ice rink.', 'https://brightwingstravel.in/images/tourImages/dubai-mall.png', 'Dubai', '1 Days', 'Adventure', 'Feb 5 - 5', 1, 'Contact Us', 40, 4, 'GTn2EKD-cfg', 'The Dubai Mall, one of the largest shopping destinations in the world, offers far more than just retail therapy. Beyond its countless luxury and high-street stores, visitors can immerse themselves in a world of entertainment, from the mesmerizing Dubai Aquarium & Underwater Zoo to the fun-filled VR Park and the Olympic-sized Ice Rink. Food lovers can enjoy a wide variety of dining options, from casual cafés to gourmet restaurants. Whether you’re shopping, exploring, or enjoying family-friendly attractions, The Dubai Mall promises a full day of unforgettable experiences for visitors of all ages', ARRAY['https://brightwingstravel.in/images/sliderImage/dubai-mall-slide-1.png', 'https://brightwingstravel.in/images/sliderImage/dubai-mall-slide-2.png', 'https://brightwingstravel.in/images/sliderImage/dubai-mall-slide-3.png', 'https://brightwingstravel.in/images/sliderImage/dubai-mall-slide-4.png']::text[], ARRAY['https://brightwingstravel.in/images/resources/dubai-mall-suggestion-1.png', 'https://brightwingstravel.in/images/resources/dubai-mall-suggestion-2.png']::text[], ARRAY['Dubai Aquarium & Underwater Zoo', 'VR Park & Indoor Theme Attractions', 'Fashion & Luxury Shopping', 'Souk & Specialty Zones', 'KidZania', 'Reel Cinemas', 'Gourmet Dining & Cafes', 'The Dubai Mall Waterfalls & Indoor Features']::text[], ARRAY['Cruise Dinner & Music Event', 'Pick and Drop Services', 'Additional Services', 'Specialized bilingual guide', 'Food and Drinks']::text[], ARRAY['Cruise Dinner & Music Event', 'Pick and Drop Services', 'Additional Services', 'Specialized bilingual guide', 'Food and Drinks']::text[], '[{"question":"Where is The Dubai Mall located?","answer":"The Dubai Mall is located in Downtown Dubai, right next to the iconic Burj Khalifa."},{"question":"Is there an entry fee to visit The Dubai Mall?","answer":"No, entry to the mall is free. However, attractions inside, like the Dubai Aquarium, Ice Rink, and VR Park, have separate ticket fees."},{"question":"What shopping options are available?","answer":"The mall offers over 1,200 stores, including luxury brands like Chanel and Gucci, high-street favorites like Zara and H&M, and unique boutique shops."},{"question":"What are the opening hours?","answer":"The mall is generally open from 10:00 AM to 12:00 AM (midnight), but individual stores and attractions may have different hours."}]'::jsonb, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3610.171509330427!2d55.27692297597464!3d25.19743797771086!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3e5f682829c85c07%3A0xa5eda9fb3c93b69d!2sDubai%20Mall!5e0!3m2!1sen!2sin!4v1760871095408!5m2!1sen!2sin', ARRAY['burj-khalifa', 'jumeirah-beach']::text[], true, 2),
    ('jumeirah-beach', 'Jumeirah Beach', 'Jumeirah Beach – Dubai’s Iconic White Sands & Crystal Waters', 'https://brightwingstravel.in/images/tourImages/jumeirah-beach.png', 'Dubai', '2 Days, 1 Night', 'Adventure', 'Feb 5 - 5', 1, 'Contact Us', 10, 5, '0MuL8fd3pb8', 'Jumeirah Beach, Dubai’s most famous shoreline, offers a perfect blend of relaxation and adventure. With its soft white sands, crystal-clear waters, and stunning views of the iconic Burj Al Arab, it’s an ideal spot for sunbathing, swimming, and watersports. Whether you’re seeking a serene escape or thrilling activities, Jumeirah Beach promises an unforgettable experience.', ARRAY['https://brightwingstravel.in/images/sliderImage/jumeirah-beach-slider-1.png', 'https://brightwingstravel.in/images/sliderImage/jumeirah-beach-slider-2.png', 'https://brightwingstravel.in/images/sliderImage/jumeirah-beach-slider-3.png', 'https://brightwingstravel.in/images/sliderImage/jumeirah-beach-slider-4.png']::text[], ARRAY['https://brightwingstravel.in/images/resources/jumeirah-beach-suggestion-1.png', 'https://brightwingstravel.in/images/resources/jumeirah-beach-suggestion-2.png']::text[], ARRAY['Dubai Aquarium & Underwater Zoo', 'VR Park & Indoor Theme Attractions', 'Fashion & Luxury Shopping', 'Souk & Specialty Zones', 'KidZania', 'Reel Cinemas', 'Gourmet Dining & Cafes', 'The Dubai Mall Waterfalls & Indoor Features']::text[], ARRAY['Cruise Dinner & Music Event', 'Pick and Drop Services', 'Additional Services', 'Specialized bilingual guide', 'Food and Drinks']::text[], ARRAY['Cruise Dinner & Music Event', 'Pick and Drop Services', 'Additional Services', 'Specialized bilingual guide', 'Food and Drinks']::text[], '[{"question":"Where is Jumeirah Beach located?","answer":"Jumeirah Beach is located along Dubai’s coast, near the iconic Burj Al Arab and Jumeirah district."},{"question":"What activities can I do at Jumeirah Beach?","answer":"Visitors can enjoy sunbathing, swimming, watersports like jet skiing and paddleboarding, beach volleyball, and photography."},{"question":"When is the best time to visit Jumeirah Beach?","answer":"The best time is from October to April when the weather is pleasant and ideal for beach activities."}]'::jsonb, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d1805.1363830224027!2d55.22967693883007!3d25.194022294428265!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3e5f42035d9872df%3A0x29698a78cf7295ef!2sJumeirah%20Beach!5e0!3m2!1sen!2sin!4v1760871145596!5m2!1sen!2sin', ARRAY['burj-al-arab', 'dubai-aquarium-underwater-zoo']::text[], true, 3),
    ('desert-safari-dubai', 'Desert Safari Dubai', 'Desert Safari – Dubai’s Golden Dunes & Thrilling Adventures', 'https://brightwingstravel.in/images/tourImages/desert-safari-dubai.png', 'Dubai', '3 Days, 2 Night', 'Adventure', 'Feb 5 - 5', 1, 'Contact Us', NULL, 4, '0MuL8fd3pb8', 'Experience the heart of Dubai’s desert with a thrilling Desert Safari, where golden dunes meet endless skies. Enjoy dune bashing in powerful 4x4s, camel rides across soft sands, and breathtaking sunset views that paint the horizon in shades of gold. As night falls, indulge in a traditional Bedouin-style camp with BBQ dinner, cultural performances, and star-lit serenity. Whether you crave adventure or a glimpse into Arabian heritage, the Desert Safari promises an unforgettable journey through Dubai’s timeless sands', ARRAY['https://brightwingstravel.in/images/sliderImage/desert-safari-slider-1.png', 'https://brightwingstravel.in/images/sliderImage/desert-safari-slider-2.png', 'https://brightwingstravel.in/images/sliderImage/desert-safari-slider-3.png', 'https://brightwingstravel.in/images/sliderImage/desert-safari-slider-4.png']::text[], ARRAY['https://brightwingstravel.in/images/resources/desert-safari-suggestion-1.png', 'https://brightwingstravel.in/images/resources/desert-safari-suggestion-2.png']::text[], ARRAY['Dune Bashing in 4x4 Vehicles', 'Camel Rides Across Golden Sands', 'Stunning Desert Sunset Views', 'Sandboarding Adventures', 'Traditional Bedouin-Style Camps', 'Cultural Performances & Belly Dancing', 'BBQ Dinner Under the Stars', 'Falconry Demonstrations & Desert Wildlife']::text[], ARRAY['Cruise Dinner & Music Event', 'Pick and Drop Services', 'Additional Services', 'Specialized bilingual guide', 'Food and Drinks']::text[], ARRAY['Cruise Dinner & Music Event', 'Pick and Drop Services', 'Additional Services', 'Specialized bilingual guide', 'Food and Drinks']::text[], '[{"question":"Where does the Desert Safari take place?","answer":"The Desert Safari takes place in the outskirts of Dubai, across the vast golden dunes of the Arabian Desert."},{"question":"What activities are included in the Desert Safari?","answer":"Activities include dune bashing in 4x4 vehicles, camel rides, sandboarding, falconry displays, cultural performances, and a BBQ dinner under the stars."},{"question":"When is the best time to go on a Desert Safari?","answer":"The best time is from October to April when the weather is cooler and ideal for desert adventures and sunset views."},{"question":"Is the Desert Safari suitable for children and elderly?","answer":"Yes, most activities are family-friendly. However, dune bashing might be intense for very young children or elderly participants, so alternatives like camel rides and cultural camps are recommended."},{"question":"Do I need to bring anything for the Desert Safari?","answer":"It is recommended to wear comfortable clothing, carry sunscreen, sunglasses, a hat, and stay hydrated. Cameras are great for capturing the stunning desert views."},{"question":"Are food and drinks provided during the Desert Safari?","answer":"Yes, most Desert Safari packages include a BBQ dinner with vegetarian and non-vegetarian options, soft drinks, and traditional refreshments at the desert camp."},{"question":"How long does the Desert Safari last?","answer":"A typical Desert Safari lasts around 6–7 hours, starting in the late afternoon and ending at night after dinner and entertainment at the desert camp."}]'::jsonb, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d115540.97402683046!2d55.185243723626975!3d25.181109734767507!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3e5f5cb5f605c7db%3A0xe5f73c2398a9a497!2sDesert%20Safaris%20Dubai!5e0!3m2!1sen!2sin!4v1760875101447!5m2!1sen!2sin', ARRAY['modern-dubai-frame', 'dubai-mall']::text[], true, 4),
    ('modern-dubai-frame', 'The modern Dubai Frame', 'The Modern Frame – Dubai’s Iconic Landmark & City Viewpoint', 'https://brightwingstravel.in/images/tourImages/the-modern-dubai-frame.png', 'Dubai', '2 Days, 1 Night', 'Adventure', 'Feb 5 - 5', 1, 'Contact Us', NULL, 5, '0MuL8fd3pb8', 'Step into the heart of modern Dubai with a visit to the iconic Dubai Frame, a stunning architectural marvel that perfectly captures the city’s past, present, and future. Soaring 150 meters high, it offers breathtaking panoramic views of both Old Dubai and the glittering skyline of New Dubai. Explore interactive exhibits that showcase the city’s transformation from a humble fishing village to a global metropolis. Whether you’re admiring the skyline from the glass bridge or capturing Instagram-worthy moments, the Dubai Frame promises a truly unforgettable experience that symbolizes Dubai’s spirit of innovation and progress.', ARRAY['https://brightwingstravel.in/images/sliderImage/dubai-frame-slider-1.png', 'https://brightwingstravel.in/images/sliderImage/dubai-frame-slider-2.png', 'https://brightwingstravel.in/images/sliderImage/dubai-frame-slider-3.png']::text[], ARRAY['https://brightwingstravel.in/images/resources/dubai-frame-suggestion-1.png', 'https://brightwingstravel.in/images/resources/dubai-frame-suggestion-2.png']::text[], ARRAY['Panoramic Views of Old and New Dubai', '150-Meter High Glass Sky Bridge Walk', 'Immersive Museum Showcasing Dubai’s Past, Present & Future', 'Stunning Architectural Landmark Framing the City Skyline', 'Interactive Exhibits and LED Displays', 'Observation Deck with 360° City Views', 'Photography Spots with Iconic Backdrops', 'Located in the Heart of Zabeel Park']::text[], ARRAY['Cruise Dinner & Music Event', 'Pick and Drop Services', 'Additional Services', 'Specialized bilingual guide', 'Food and Drinks']::text[], ARRAY['Cruise Dinner & Music Event', 'Pick and Drop Services', 'Additional Services', 'Specialized bilingual guide', 'Food and Drinks']::text[], '[{"question":"What is the Dubai Frame?","answer":"The Dubai Frame is a modern architectural landmark that offers panoramic views of both old and new Dubai, symbolizing the city’s transformation from a fishing village to a global metropolis."},{"question":"Where is the Dubai Frame located?","answer":"The Dubai Frame is located in Zabeel Park, one of Dubai’s largest and most beautiful green spaces, easily accessible from major city areas."},{"question":"What can visitors see from the top of the Dubai Frame?","answer":"From the Sky Deck at 150 meters high, visitors can view modern Dubai’s skyline on one side and the historic parts of the city on the other, connected by a glass-floored bridge."},{"question":"What are the visiting hours of the Dubai Frame?","answer":"The Dubai Frame is open daily from 9:00 AM to 9:00 PM, but timings may vary during public holidays or special events."},{"question":"Is there an entry fee for the Dubai Frame?","answer":"Yes, there is an entry fee. As of now, general admission tickets cost around AED 50 for adults and AED 20 for children, while entry is free for kids under 3 and people of determination."}]'::jsonb, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3609.043726004866!2d55.29776597597551!3d25.23545217768636!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3e5f42db20d99d41%3A0xf93035af01a85798!2sDubai%20Frame!5e0!3m2!1sen!2sin!4v1760882114763!5m2!1sen!2sin', ARRAY['desert-safari-dubai', 'dubai-aquarium-underwater-zoo']::text[], false, 5),
    ('burj-al-arab', 'Burj Al Arab', 'Burj Al Arab – Dubai’s Iconic Sail-Shaped Wonder & Luxury Experience', 'https://brightwingstravel.in/images/tourImages/burj-al-arab.png', 'Dubai', '4 Days, 3 Night', 'Adventure', 'Feb 5 - 5', 1, 'Contact Us', NULL, 4, '0MuL8fd3pb8', 'Experience the epitome of luxury and architectural brilliance with a visit to the Burj Al Arab, Dubai’s world-famous sail-shaped hotel. Rising gracefully from its own private island, this iconic landmark redefines opulence and innovation. Step inside to witness stunning interiors adorned with gold accents, grand atriums, and breathtaking sea views that showcase the finest in modern design. Whether you’re dining at one of its award-winning restaurants, relaxing at the exclusive terrace, or simply admiring its majestic presence from Jumeirah Beach, the Burj Al Arab offers an unforgettable glimpse into Dubai’s unmatched hospitality and elegance.', ARRAY['https://brightwingstravel.in/images/sliderImage/burj-al-arab-slider-1.png', 'https://brightwingstravel.in/images/sliderImage/burj-al-arab-slider-2.png', 'https://brightwingstravel.in/images/sliderImage/burj-al-arab-slider-3.png', 'https://brightwingstravel.in/images/sliderImage/burj-al-arab-slider-4.png']::text[], ARRAY['https://brightwingstravel.in/images/resources/burj-al-arab-suggestion-1.png', 'https://brightwingstravel.in/images/resources/burj-al-arab-suggestion-2.png']::text[], ARRAY['Iconic Sail-Shaped Architectural Design', 'World’s Most Luxurious 7-Star Hotel Experience', 'Exclusive Access to Private Island Location', 'Panoramic Views of the Arabian Gulf and Dubai Skyline', 'Lavish Interiors Adorned with Gold and Marble', 'Award-Winning Fine Dining Restaurants', 'Helipad Offering Stunning Aerial Views', 'Private Beach and Terrace with Infinity Pools']::text[], ARRAY['Cruise Dinner & Music Event', 'Pick and Drop Services', 'Additional Services', 'Specialized bilingual guide', 'Food and Drinks']::text[], ARRAY['Cruise Dinner & Music Event', 'Pick and Drop Services', 'Additional Services', 'Specialized bilingual guide', 'Food and Drinks']::text[], '[{"question":"What is the Burj Al Arab?","answer":"The Burj Al Arab is one of Dubai’s most iconic landmarks, known as the world’s only 7-star hotel. Shaped like a sail, it represents luxury, innovation, and architectural excellence on Dubai’s coastline."},{"question":"Where is the Burj Al Arab located?","answer":"The Burj Al Arab is located on its own private island off Jumeirah Beach, connected to the mainland by a private bridge in the Jumeirah area of Dubai."},{"question":"Can visitors enter the Burj Al Arab without staying there?","answer":"Yes, visitors can experience the Burj Al Arab through guided tours, afternoon tea, or dining reservations at its world-renowned restaurants without being hotel guests."},{"question":"What are the visiting hours of the Burj Al Arab?","answer":"Visiting hours vary depending on reservations and experiences, but tours and dining options are typically available from 10:00 AM to 8:00 PM daily."},{"question":"What makes the Burj Al Arab special?","answer":"The Burj Al Arab is famous for its sail-shaped design, luxurious interiors decorated with gold leaf, personalized butler service, and breathtaking views of the Arabian Gulf and Dubai skyline."}]'::jsonb, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3611.28741746799!2d55.20057578560149!3d25.159771220326586!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3e5f6be81e5c4d0f%3A0x7ef4344209b0b62!2sBURJ%20AL%20ARAB%20BEACH!5e0!3m2!1sen!2sin!4v1760882169361!5m2!1sen!2sin', ARRAY['burj-khalifa', 'jumeirah-beach']::text[], false, 6),
    ('dubai-aquarium-underwater-zoo', 'houses the Dubai Aquarium & Underwater Zoo', 'Dubai Aquarium & Underwater Zoo – A Captivating Marine World in the Heart of the City', 'https://brightwingstravel.in/images/tourImages/houses-the-dubai-aquarium.png', 'Dubai', '1 Days', 'Adventure', 'Feb 5 - 5', 1, 'Contact Us', 20, 4, '0MuL8fd3pb8', 'Dive into a world of wonder at the Dubai Aquarium & Underwater Zoo, one of the largest suspended aquariums in the world, located inside The Dubai Mall. Home to thousands of aquatic animals, including sharks, rays, and exotic fish, it offers an incredible glimpse into the beauty of marine life. Walk through the 48-meter-long underwater tunnel and feel surrounded by the ocean as sea creatures glide above and around you. Explore the Underwater Zoo on the upper level to meet penguins, crocodiles, and other fascinating species. Whether you’re visiting with family or friends, the Dubai Aquarium & Underwater Zoo promises an awe-inspiring journey through the depths of the sea right in the heart of the city.', ARRAY['https://brightwingstravel.in/images/sliderImage/dubai-aquarium-slider-1.png', 'https://brightwingstravel.in/images/sliderImage/dubai-aquarium-slider-2.png', 'https://brightwingstravel.in/images/sliderImage/dubai-aquarium-slider-3.png']::text[], ARRAY['https://brightwingstravel.in/images/resources/dubai-aquarium-suggestion-1.png', 'https://brightwingstravel.in/images/resources/dubai-aquarium-suggestion-2.png']::text[], ARRAY['World’s Largest Suspended Aquarium', '48-Meter Underwater Tunnel', 'Sharks, Rays & Exotic Marine Life', 'Underwater Zoo with Penguins & Crocodiles', 'Interactive Touch Pools', 'Glass Walkways with Ocean Views', 'Family-Friendly Experience', 'Located in The Dubai Mall']::text[], ARRAY['Cruise Dinner & Music Event', 'Pick and Drop Services', 'Additional Services', 'Specialized bilingual guide', 'Food and Drinks']::text[], ARRAY['Cruise Dinner & Music Event', 'Pick and Drop Services', 'Additional Services', 'Specialized bilingual guide', 'Food and Drinks']::text[], '[{"question":"What is the Dubai Aquarium & Underwater Zoo?","answer":"The Dubai Aquarium & Underwater Zoo is one of the world’s largest suspended aquariums, home to thousands of marine animals including sharks, rays, and exotic fish, along with an upper-level zoo featuring penguins, crocodiles, and other fascinating species."},{"question":"Where is the Dubai Aquarium & Underwater Zoo located?","answer":"It is located inside The Dubai Mall, in the heart of Downtown Dubai, making it easily accessible for visitors exploring the city’s central attractions."},{"question":"What can visitors see and do at the Dubai Aquarium & Underwater Zoo?","answer":"Visitors can walk through the 48-meter-long underwater tunnel, explore the Underwater Zoo, interact with touch pools, see educational exhibits, and capture amazing photos of marine life."},{"question":"What are the visiting hours of the Dubai Aquarium & Underwater Zoo?","answer":"The aquarium and zoo are typically open daily from 10:00 AM to 10:00 PM, though timings may vary during holidays or special events."},{"question":"Is there an entry fee for the Dubai Aquarium & Underwater Zoo?","answer":"Yes, there is an entry fee. General admission tickets include access to the aquarium and the Underwater Zoo, while special experiences like cage snorkeling or shark diving are available at additional cost."}]'::jsonb, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3610.169273979546!2d55.27592557597451!3d25.197513377710727!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3e5f43496ad9c645%3A0x230b55e177a8dd29!2sDubai%20Aquarium%20%26%20Underwater%20Zoo!5e0!3m2!1sen!2sin!4v1760882200160!5m2!1sen!2sin', ARRAY['desert-safari-dubai', 'dubai-mall']::text[], false, 7)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO tour_reviews (tour_id, name, message, rating, status, created_at)
SELECT t.id, r.name, r.message, r.rating, 'approved', r.created_at::timestamptz
FROM (VALUES
    ('burj-khalifa', 'Leslie Alexander', 'Visiting Burj Khalifa was unforgettable! The views from the observation deck are absolutely breathtaking, offering a stunning panorama of Dubai’s skyline and desert. The experience of being at the world’s tallest building is truly surreal.', 4, '2024-02-10T09:07:00.000Z'),
    ('dubai-mall', 'Leslie Alexander', 'The Dubai Mall is amazing! It has everything – from high-end shopping to incredible attractions like the Dubai Aquarium and the indoor waterfall. The food courts and entertainment options make it perfect for a full day out. Truly a must-visit in Dubai!', 4, '2024-02-10T09:07:00.000Z'),
    ('jumeirah-beach', 'Leslie Alexander', 'Jumeirah Beach is beautiful and relaxing! The soft white sand and clear blue waters are perfect for sunbathing and swimming. The view of the Burj Al Arab in the background makes it even more special. A great spot to unwind and enjoy the sea in Dubai', 4, '2024-02-10T09:07:00.000Z'),
    ('desert-safari-dubai', 'Leslie Alexander', 'The Dubai Desert Safari was absolutely thrilling! Dune bashing in the 4x4 was so much fun, and the camel rides and sandboarding added to the adventure. The desert sunset was stunning, and the cultural performances with a BBQ dinner under the stars made it a perfect evening.', 4, '2024-02-10T09:07:00.000Z'),
    ('modern-dubai-frame', 'Leslie Alexander', 'Visiting the Dubai Frame was an incredible experience! The views from the Sky Deck are breathtaking, showing both Old and New Dubai. Walking on the glass bridge was thrilling, and the exhibits inside beautifully showcase the city’s history and growth. Highly recommend it!', 4, '2024-02-10T09:07:00.000Z'),
    ('burj-al-arab', 'Leslie Alexander', 'Absolutely stunning! The white sands and clear waters make it the perfect spot to relax and take in the view of the Burj Al Arab.', 4, '2024-02-10T09:07:00.000Z'),
    ('dubai-aquarium-underwater-zoo', 'Leslie Alexander', 'Absolutely loved visiting the Dubai Aquarium! The underwater tunnel was amazing, and seeing the sharks and rays up close was unforgettable. The Underwater Zoo on the upper level is fun for kids and adults alike. A must-visit for anyone in Dubai!', 4, '2024-02-10T09:07:00.000Z')
) AS r(slug, name, message, rating, created_at)
JOIN tours t ON t.slug = r.slug
WHERE NOT EXISTS (SELECT 1 FROM tour_reviews x WHERE x.tour_id = t.id);
